// N8N Text Splitter Code
// This code splits an input text into 4 equal parts without cutting words in half.

// Here n8n will provide an items array which contains the incoming data
// The return value must be an array of items
return items.map((item) => {
  // Get the text from the item
  let textToSplit = item.json.text || '';

  // Ensure we have text to process
  if (typeof textToSplit !== 'string') {
    textToSplit = String(textToSplit || '');
  }

  // Function to find the nearest word boundary (space)
  function findNearestWordBoundary(text, targetPosition) {
    // If we're at the start or end, return that position
    if (targetPosition <= 0) return 0;
    if (targetPosition >= text.length) return text.length;

    // If target position is already at a space, return it
    if (text[targetPosition] === ' ') return targetPosition;

    // Look forward and backward for the nearest space
    let forwardPos = targetPosition;
    let backwardPos = targetPosition;

    // Search forward
    while (forwardPos < text.length && text[forwardPos] !== ' ') {
      forwardPos++;
    }

    // Search backward
    while (backwardPos > 0 && text[backwardPos] !== ' ') {
      backwardPos--;
    }

    // If we found spaces in both directions, pick the closest one
    if (forwardPos < text.length && backwardPos > 0) {
      return (forwardPos - targetPosition) < (targetPosition - backwardPos) 
        ? forwardPos : backwardPos + 1; // +1 to start after the space
    }

    // If we only found a space in one direction, use that
    if (forwardPos < text.length) return forwardPos;
    if (backwardPos > 0) return backwardPos + 1; // +1 to start after the space

    // If no space was found (rare case with very long words), default to target position
    return targetPosition;
  }

  // Calculate ideal split positions (these might cut words)
  const textLength = textToSplit.length;
  const idealPartLength = Math.ceil(textLength / 4);

  // Find actual split positions at word boundaries
  const splitPos1 = findNearestWordBoundary(textToSplit, idealPartLength);
  const splitPos2 = findNearestWordBoundary(textToSplit, splitPos1 + idealPartLength);
  const splitPos3 = findNearestWordBoundary(textToSplit, splitPos2 + idealPartLength);

  // Split the text at the word boundaries
  const parts = [
    textToSplit.substring(0, splitPos1).trim(),
    textToSplit.substring(splitPos1, splitPos2).trim(),
    textToSplit.substring(splitPos2, splitPos3).trim(),
    textToSplit.substring(splitPos3).trim()
  ];

  // Create a new output item with all the original properties
  const newItem = { ...item.json };

  // Add the parts to the output
  newItem.part1 = parts[0];
  newItem.part2 = parts[1];
  newItem.part3 = parts[2];
  newItem.part4 = parts[3];
  newItem.parts = parts;

  // Return the new item in the format n8n expects
  return {
    json: newItem
  };
});

// N8N Code Node to remove all newline characters from previous node outputs

// Process all items in the array
// This will work regardless of whether we're running once for all items or once per item
for (let i = 0; i < items.length; i++) {
  const currentItem = items[i];

  // Check if the item has an output property
  if (currentItem.json && currentItem.json.output !== undefined) {
    // Replace all newline characters with empty string
    // Using a global regex to catch ALL instances of \n
    currentItem.json.output = currentItem.json.output.replace(/\\n/g, '');

    // Also replace actual newline characters if they exist
    currentItem.json.output = currentItem.json.output.replace(/\n/g, '');
  }
}

// Return the processed items array
return items;

// Code to extract video URLs from JSON data in n8n
// This handles various possible input structures

// Function to extract video info if the object has the expected structure
function extractVideoInfo(obj, index) {
  if (obj && obj.code === 200 && 
      obj.data && obj.data.output && obj.data.output.video_url) {
    return {
      index: index,
      taskId: obj.data.task_id,
      videoUrl: obj.data.output.video_url,
      prompt: obj.data.input.prompt
    };
  }
  return null;
}

// Initialize results array
const videoUrls = [];
let currentIndex = 1;

// n8n specific: loop through all items
for (const item of items) {
  // Case 1: item.json is our array
  if (Array.isArray(item.json)) {
    item.json.forEach(entry => {
      const videoInfo = extractVideoInfo(entry, currentIndex);
      if (videoInfo) {
        videoUrls.push(videoInfo);
        currentIndex++;
      }
    });
  } 
  // Case 2: item.json is a single object with our data
  else if (typeof item.json === 'object') {
    const videoInfo = extractVideoInfo(item.json, currentIndex);
    if (videoInfo) {
      videoUrls.push(videoInfo);
      currentIndex++;
    }

    // Case 3: item.json has a data property that is our array
    if (Array.isArray(item.json.data)) {
      item.json.data.forEach(entry => {
        const videoInfo = extractVideoInfo(entry, currentIndex);
        if (videoInfo) {
          videoUrls.push(videoInfo);
          currentIndex++;
        }
      });
    }
  }

  // Log what we're working with to help with debugging
  console.log('Processing item:', JSON.stringify(item.json).substring(0, 200) + '...');
}

// Return the extracted URLs as the output
return [{
  json: {
    totalVideos: videoUrls.length,
    videos: videoUrls
  }
}];
